class Solution:
    def maxArrayValue(self, nums: List[int]) -> int:
        current = nums[-1]
        max_val = current
        for i in range(len(nums) - 2, -1, -1):
            if nums[i] <= current:
                current += nums[i]
            else:
                current = nums[i]
            max_val = max(max_val, current)
        return max_val

