class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        n = len(nums)
        if n == 1:
            return True

        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if rank[rx] < rank[ry]:
                rx, ry = ry, rx
            parent[ry] = rx
            if rank[rx] == rank[ry]:
                rank[rx] += 1

        prime_to_idx = {}

        for i, num in enumerate(nums):
            temp = num
            d = 2
            factors = []
            while d * d <= temp:
                if temp % d == 0:
                    factors.append(d)
                    while temp % d == 0:
                        temp //= d
                d += 1
            if temp > 1:
                factors.append(temp)

            for p in factors:
                if p in prime_to_idx:
                    union(i, prime_to_idx[p])
                else:
                    prime_to_idx[p] = i

        root = find(0)
        return all(find(i) == root for i in range(n))

def main():
    input_data = sys.stdin.read().split()
    nums = list(map(int, input_data))
    sol = Solution()
    print(sol.canTraverseAllPairs(nums))

if __name__ == "__main__":
