class Solution:
    def canSortArray(self, nums: List[int]) -> bool:
        n = len(nums)
        arr = nums[:]
        # Bubble sort, but only swap if same number of set bits
        for i in range(n):
            for j in range(n - 1):
                if arr[j] > arr[j+1]:
                    if bin(arr[j]).count('1') == bin(arr[j+1]).count('1'):
                        arr[j], arr[j+1] = arr[j+1], arr[j]
        return arr == sorted(nums)

