class Solution:
    def minimizeConcatenatedLength(self, words: List[str]) -> int:
        n = len(words)
        w0 = words[0]
        current = {}
        current[(w0[0], w0[-1])] = len(w0)

        for i in range(1, n):
            word = words[i]
            wf, wl = word[0], word[-1]
            wlen = len(word)
            next_dp = {}

            for (first, last), length in current.items():
                # Option 1: join(current_str, word)
                new_len1 = length + wlen - (1 if last == wf else 0)
                key1 = (first, wl)
                if key1 not in next_dp or next_dp[key1] > new_len1:
                    next_dp[key1] = new_len1

                # Option 2: join(word, current_str)
                new_len2 = length + wlen - (1 if wl == first else 0)
                key2 = (wf, last)
                if key2 not in next_dp or next_dp[key2] > new_len2:
                    next_dp[key2] = new_len2

            current = next_dp

        return min(current.values())

