from collections import defaultdict

def main():
    input_data = sys.stdin.buffer.read().split()
    idx = 0
    N, M = int(input_data[idx]), int(input_data[idx+1]); idx += 2

    children = defaultdict(list)
    for i in range(2, N+1):
        p = int(input_data[idx]); idx += 1
        children[p].append(i)

    # Iterative DFS for tin, tout, depth
    tin = [0] * (N+1)
    tout = [0] * (N+1)
    depth = [0] * (N+1)

    stack = [(1, False)]
    t = 0
    while stack:
        node, leaving = stack.pop()
        if leaving:
            tout[node] = t - 1
        else:
            tin[node] = t
            t += 1
            stack.append((node, True))
            for c in reversed(children[node]):
                depth[c] = depth[node] + 1
                stack.append((c, False))

    # Group insurances by max_depth
    ins_by_maxdepth = defaultdict(list)
    for _ in range(M):
        x, y = int(input_data[idx]), int(input_data[idx+1]); idx += 2
        max_d = depth[x] + y
        ins_by_maxdepth[max_d].append(x)

    # BIT for range update point query
    bit = [0] * (N + 2)
    def update(l, r, val):
        l += 1; r += 2
        while l <= N+1:
            bit[l] += val; l += l & (-l)
        while r <= N+1:
            bit[r] -= val; r += r & (-r)
    def query(i):
        i += 1; s = 0
        while i > 0:
            s += bit[i]; i -= i & (-i)
        return s

    # Group nodes by depth
    nodes_by_depth = defaultdict(list)
    for v in range(1, N+1):
        nodes_by_depth[depth[v]].append(v)

    max_possible_depth = max(depth[1:N+1]) if N > 0 else 0
    max_ins_depth = max(ins_by_maxdepth.keys()) if ins_by_maxdepth else 0

    count = 0
    for d in range(max(max_possible_depth, max_ins_depth) + 1):
        if d in ins_by_maxdepth:
            for x in ins_by_maxdepth[d]:
                update(tin[x], tout[x], 1)
        if d in nodes_by_depth:
            for v in nodes_by_depth[d]:
                if query(tin[v]) > 0:
                    count += 1

    print(count)

