import sys

def largest_pow2_leq(n):
    return 1 << (n.bit_length() - 1)

def solve():
    line = input().split()
    L, R = int(line[0]), int(line[1])

    result = []
    cur = L
    while cur < R:
        remaining = R - cur
        if cur == 0:
            step = largest_pow2_leq(remaining)
        else:
            low_bit = cur & (-cur)
            max_step = largest_pow2_leq(remaining)
            step = min(low_bit, max_step)
        result.append((cur, cur + step))
        cur += step

    print(len(result))
    for l, r in result:
        print(l, r)

