class Solution:
    def findMinimumOperations(self, s1: str, s2: str, s3: str) -> int:
        min_len = min(len(s1), len(s2), len(s3))
        # Find longest common prefix of all three
        common = 0
        for i in range(min_len):
            if s1[i] == s2[i] == s3[i]:
                common += 1
            else:
                break
        if common == 0:
            return -1
        return (len(s1) - common) + (len(s2) - common) + (len(s3) - common)

