def pluck(arr):
    if not arr:
        return []
    evens = [(v, i) for i, v in enumerate(arr) if v % 2 == 0]
    if not evens:
        return []
    min_val, min_idx = min(evens, key=lambda x: (x[0], x[1]))
    return [min_val, min_idx]

