from math import inf

def solve():
    data = sys.stdin.read().split()
    s = data[0]
    k = int(data[1])

    n = len(s)

    cost = [[inf] * n for _ in range(n)]

    for i in range(n):
        for j in range(i+1, n):
            L = j - i + 1
            best = inf
            for d in range(1, L):
                if L % d == 0:
                    changes = 0
                    for r in range(d):
                        group = []
                        idx2 = r
                        while idx2 < L:
                            group.append(s[i + idx2])
                            idx2 += d
                        lo, hi = 0, len(group) - 1
                        while lo < hi:
                            if group[lo] != group[hi]:
                                changes += 1
                            lo += 1
                            hi -= 1
                    best = min(best, changes)
            cost[i][j] = best

    dp = [[inf] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0

    for p in range(1, k + 1):
        for i in range(p, n + 1):
            for j in range(p - 1, i):
                if i - j < 2:
                    continue
                if dp[p-1][j] == inf:
                    continue
                c = cost[j][i-1]
                if c != inf:
                    if dp[p-1][j] + c < dp[p][i]:
                        dp[p][i] = dp[p-1][j] + c

    print(dp[k][n])

