class Solution:
    def alternatingSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        ans = -1
        for i in range(n):
            for j in range(i + 1, n):
                # Check if nums[i..j] is alternating
                length = j - i + 1
                s0 = nums[i]
                s1 = nums[i] + 1
                valid = True
                for k in range(i, j + 1):
                    if (k - i) % 2 == 0:
                        if nums[k] != s0:
                            valid = False
                            break
                    else:
                        if nums[k] != s1:
                            valid = False
                            break
                if valid:
                    ans = max(ans, length)
        return ans

