from typing import List

class TrieNode:
    def __init__(self):
        self.children = {}
        self.best = -1

class Solution:
    def stringIndices(self, wordsContainer: List[str], wordsQuery: List[str]) -> List[int]:
        root = TrieNode()

        def is_better(new_idx, best_idx):
            if best_idx == -1:
                return True
            if len(wordsContainer[new_idx]) < len(wordsContainer[best_idx]):
                return True
            if len(wordsContainer[new_idx]) == len(wordsContainer[best_idx]) and new_idx < best_idx:
                return True
            return False

        for i, word in enumerate(wordsContainer):
            node = root
            if is_better(i, node.best):
                node.best = i
            for ch in reversed(word):
                if ch not in node.children:
                    node.children[ch] = TrieNode()
                node = node.children[ch]
                if is_better(i, node.best):
                    node.best = i

        ans = []
        for query in wordsQuery:
