def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    N = int(input_data[idx]); idx += 1
    A = []
    B = []
    for i in range(N):
        a = int(input_data[idx]); idx += 1
        b = int(input_data[idx]); idx += 1
        A.append(a)
        B.append(b)

    # Precompute valid pairs
    valid_pairs = []
    for i in range(N):
        for j in range(i+1, N):
            if A[i] == A[j] or B[i] == B[j]:
                valid_pairs.append((i, j))

    # DP: dp[mask] = True if current player wins
    # mask represents the set of cards currently on the table
    # dp[0] = False (losing position - can't move)
    dp = [False] * (1 << N)

    for mask in range(1, 1 << N):
        # Try all valid pairs where both cards are in mask
        for (i, j) in valid_pairs:
            if (mask >> i) & 1 and (mask >> j) & 1:
                new_mask = mask ^ (1 << i) ^ (1 << j)
                if not dp[new_mask]:
                    dp[mask] = True
                    break

    full_mask = (1 << N) - 1
    if dp[full_mask]:
        print("Takahashi")
    else:
        print("Aoki")

