class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)

        def solve(a, b, extra_cost):
            cost = extra_cost
            for i in range(n - 1):
                x, y = nums1[i], nums2[i]
                if x <= a and y <= b:
                    continue
                elif y <= a and x <= b:
                    cost += 1
                else:
                    return float('inf')
            return cost

        a, b = nums1[n-1], nums2[n-1]
        res_a = solve(a, b, 0)

        a, b = nums2[n-1], nums1[n-1]
        res_b = solve(a, b, 1)

        ans = min(res_a, res_b)
        return ans if ans != float('inf') else -1

