class Solution:
    def minimumRightShifts(self, nums: List[int]) -> int:
        n = len(nums)

        drops = 0
        drop_idx = -1
        for i in range(n - 1):
            if nums[i] > nums[i + 1]:
                drops += 1
                drop_idx = i

        if drops == 0:
            return 0

        if drops > 1:
            return -1

        # Exactly one drop at drop_idx
        # After n - (drop_idx+1) right shifts, the array should be sorted
        # Also need nums[-1] < nums[0] for the rotation to be valid
        if nums[n-1] < nums[0]:
            return n - (drop_idx + 1)
        else:
            return -1

