class Solution:
    def smallestString(self, s: str) -> str:
        n = len(s)
        chars = list(s)

        # Find first non-'a' character
        start = -1
        for i in range(n):
            if chars[i] != 'a':
                start = i
                break

        # If all 'a's, apply to last character only
        if start == -1:
            chars[-1] = 'z'
            return ''.join(chars)

        # Apply operation from start, continue while not 'a'
        i = start
        while i < n and chars[i] != 'a':
            chars[i] = chr(ord(chars[i]) - 1)
            i += 1

        return ''.join(chars)

