class Solution:
    def minimumCost(self, nums: List[int]) -> int:
        nums.sort()
        n = len(nums)
        median = nums[n // 2]

        def get_palindrome_candidates(m):
            candidates = []
            s = str(m)
            length = len(s)
            half = (length + 1) // 2
            prefix = s[:half]
            for delta in [-1, 0, 1]:
                p = int(prefix) + delta
                if p <= 0:
                    continue
                ps = str(p)
                if length % 2 == 0:
                    pal = ps + ps[::-1]
                else:
                    pal = ps + ps[-2::-1]
                val = int(pal)
                if val > 0:
                    candidates.append(val)
            # Edge cases around digit boundaries
            for exp in [length - 1, length]:
                candidates.append(10**exp - 1)
                candidates.append(10**exp + 1)
            return [c for c in candidates if 0 < c < 10**9]

        def cost(y):
            return sum(abs(x - y) for x in nums)

        candidates = get_palindrome_candidates(median)
        # Also try median - 1 and median + 1 positions
        if n % 2 == 0:
            median2 = nums[n // 2 - 1]
            candidates += get_palindrome_candidates(median2)

        return min(cost(c) for c in candidates if c > 0)

