class Solution:
    def maximumXorProduct(self, a: int, b: int, n: int) -> int:
        MOD = 10**9 + 7
        A = (a >> n) << n
        B = (b >> n) << n
        for i in range(n - 1, -1, -1):
            a_bit = (a >> i) & 1
            b_bit = (b >> i) & 1
            if a_bit == b_bit:
                A |= (1 << i)
                B |= (1 << i)
            else:
                if A <= B:
                    A |= (1 << i)
                else:
                    B |= (1 << i)
        return (A % MOD) * (B % MOD) % MOD

