class Solution:
    def minimumDeletions(self, word: str, k: int) -> int:
        freq = sorted(Counter(word).values())

        min_deletions = float('inf')

        candidates = [0] + freq
        for f in candidates:
            deletions = 0
            for fj in freq:
                if fj < f:
                    deletions += fj
                elif fj > f + k:
                    deletions += fj - (f + k)
            min_deletions = min(min_deletions, deletions)

        return min_deletions

