def solve():
    MOD = 998244353
    input_data = stdin.read().split()
    H, W = int(input_data[0]), int(input_data[1])
    S = [input_data[2+i] for i in range(H)]

    parent = list(range(H*W))
    rank = [0]*(H*W)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry: return
        if rank[rx] < rank[ry]: rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]: rank[rx] += 1

    for i in range(H):
        for j in range(W):
            if S[i][j] == '#':
                if i+1 < H and S[i+1][j] == '#':
                    union(i*W+j, (i+1)*W+j)
                if j+1 < W and S[i][j+1] == '#':
                    union(i*W+j, i*W+j+1)

    green_roots = set()
    for i in range(H):
        for j in range(W):
            if S[i][j] == '#':
                green_roots.add(find(i*W+j))
    C = len(green_roots)

    total_merges = 0
    red_count = 0
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]
    for i in range(H):
        for j in range(W):
            if S[i][j] == '.':
                red_count += 1
                adj_roots = set()
                for di, dj in dirs:
                    ni, nj = i+di, j+dj
                    if 0 <= ni < H and 0 <= nj < W and S[ni][nj] == '#':
                        adj_roots.add(find(ni*W+nj))
                total_merges += len(adj_roots)

    numerator = C * red_count + red_count - total_merges
    denominator = red_count

    inv_denom = pow(denominator, MOD-2, MOD)
    ans = (numerator % MOD * inv_denom) % MOD
    print(ans)

solve()

