from functools import lru_cache

def solve():
    MOD = 10**9 + 7
    data = sys.stdin.read().split()
    low = data[0].strip()
    high = data[1].strip()

    def is_stepping(s):
        for i in range(1, len(s)):
            if abs(int(s[i]) - int(s[i-1])) != 1:
                return False
        return True

    def count_up_to(s):
        n = len(s)

        @lru_cache(maxsize=None)
        def dp(pos, last_digit, tight, started):
            if pos == n:
                return 1 if started else 0
            limit = int(s[pos]) if tight else 9
            result = 0
            for d in range(0, limit + 1):
                new_tight = tight and (d == limit)
                if not started:
                    if d == 0:
                        result += dp(pos + 1, -1, new_tight, False)
                    else:
                        result += dp(pos + 1, d, new_tight, True)
                else:
                    if abs(d - last_digit) == 1:
                        result += dp(pos + 1, d, new_tight, True)
            return result % MOD

        ans = dp(0, -1, True, False)
        dp.cache_clear()
        return ans

    ans = (count_up_to(high) - count_up_to(low) + (1 if is_stepping(low) else 0) + MOD) % MOD
    print(ans)

