class Solution:
    def minOperationsToMakeMedianK(self, nums: List[int], k: int) -> int:
        nums.sort()
        n = len(nums)
        m = n // 2
        ops = 0

        # Elements at index <= m that are greater than k need to come down to k
        for i in range(m, -1, -1):
            if nums[i] > k:
                ops += nums[i] - k
            else:
                break

        # Elements at index >= m that are less than k need to go up to k
        for i in range(m, n):
            if nums[i] < k:
                ops += k - nums[i]
            else:
                break

        return ops

