class Solution:
    def punishmentNumber(self, n: int) -> int:
        def can_partition(s, target):
            if not s and target == 0:
                return True
            if not s:
                return False
            for i in range(1, len(s) + 1):
                prefix = int(s[:i])
                if prefix <= target and can_partition(s[i:], target - prefix):
                    return True
            return False

        result = 0
        for i in range(1, n + 1):
            sq = i * i
            if can_partition(str(sq), i):
                result += sq
        return result

