class Solution:
    def maxPalindromesAfterOperations(self, words: List[str]) -> int:
        total = Counter()
        for w in words:
            total += Counter(w)

        pairs = sum(v // 2 for v in total.values())
        odds = sum(v % 2 for v in total.values())

        lengths = sorted(len(w) for w in words)

        count = 0
        for length in lengths:
            need_pairs = length // 2
            need_odd = length % 2

            if pairs >= need_pairs:
                pairs -= need_pairs
                if need_odd:
                    if odds > 0:
                        odds -= 1
                    else:
                        if pairs > 0:
                            pairs -= 1
                            odds += 1
                            odds -= 1
                        else:
                            break
                count += 1
            else:
                break

        return count

