class Solution:
    def minimumOperations(self, num: str) -> int:
        n = len(num)
        ans = n  # worst case: delete all digits to get 0 (divisible by 25)

        for ending in ["00", "25", "50", "75"]:
            a, b = ending[0], ending[1]
            # Try all positions for b (the last digit)
            for i in range(n - 1, -1, -1):
                if num[i] == b:
                    # Find rightmost a before position i
                    for j in range(i - 1, -1, -1):
                        if num[j] == a:
                            # cost = remove digits after i + remove digits between j and i
                            cost = (n - 1 - i) + (i - 1 - j)
                            ans = min(ans, cost)
                            break
                    break  # Only need rightmost b for minimum cost

        return ans

