def main():
    input_data = sys.stdin.read().split()
    idx = 0
    N = int(input_data[idx]); idx += 1

    prereqs = []
    for i in range(N):
        c = int(input_data[idx]); idx += 1
        books = []
        for j in range(c):
            books.append(int(input_data[idx])); idx += 1
        prereqs.append(books)

    # Find all required books (1-indexed)
    required = set()
    queue = deque([1])
    visited = set([1])
    while queue:
        book = queue.popleft()
        for p in prereqs[book-1]:
            if p not in visited:
                visited.add(p)
                required.add(p)
                queue.append(p)

    nodes = required | {1}

    in_degree = {node: 0 for node in nodes}
    adj = {node: [] for node in nodes}

    for node in nodes:
        for p in prereqs[node-1]:
            if p in nodes:
                in_degree[node] += 1
                adj[p].append(node)

    q = deque()
    for node in nodes:
        if in_degree[node] == 0:
            q.append(node)

    order = []
    while q:
        node = q.popleft()
        order.append(node)
        for nxt in adj[node]:
            in_degree[nxt] -= 1
            if in_degree[nxt] == 0:
                q.append(nxt)

    result = [str(x) for x in order if x != 1]
    print(' '.join(result))

