class Solution:
    def minimumDistance(self, points: List[List[int]]) -> int:
        n = len(points)
        s = [x + y for x, y in points]
        d = [x - y for x, y in points]

        def top2_max(arr):
            indexed = sorted(enumerate(arr), key=lambda x: -x[1])
            return indexed[:2]

        def top2_min(arr):
            indexed = sorted(enumerate(arr), key=lambda x: x[1])
            return indexed[:2]

        s_max2 = top2_max(s)
        s_min2 = top2_min(s)
        d_max2 = top2_max(d)
        d_min2 = top2_min(d)

        candidates = set()
        for idx, val in s_max2: candidates.add(idx)
        for idx, val in s_min2: candidates.add(idx)
        for idx, val in d_max2: candidates.add(idx)
        for idx, val in d_min2: candidates.add(idx)

        def get_best_val(top2_max_list, top2_min_list, removed):
            mx = None
            for idx, val in top2_max_list:
                if idx != removed:
                    mx = val
                    break
            mn = None
            for idx, val in top2_min_list:
                if idx != removed:
                    mn = val
                    break
            if mx is None or mn is None:
                return 0
            return mx - mn

        ans = float('inf')
        for rem in candidates:
            dist_s = get_best_val(s_max2, s_min2, rem)
            dist_d = get_best_val(d_max2, d_min2, rem)
            ans = min(ans, max(dist_s, dist_d))

        return ans

