class Solution:
    def minimumValueSum(self, nums: List[int], andValues: List[int]) -> int:
        INF = float('inf')
        n, m = len(nums), len(andValues)

        prev = {-1: 0}

        for j in range(m):
            target = andValues[j]
            curr = {}
            groups = []  # list of [and_val, min_prev_cost]

            for i in range(n):
                new_groups = []
                for (av, mc) in groups:
                    nv = av & nums[i]
                    if new_groups and new_groups[-1][0] == nv:
                        if mc < new_groups[-1][1]:
                            new_groups[-1][1] = mc
                    else:
                        new_groups.append([nv, mc])
                groups = new_groups

                if (i - 1) in prev:
                    cost = prev[i - 1]
                    nv = nums[i]
                    if groups and groups[-1][0] == nv:
                        if cost < groups[-1][1]:
                            groups[-1][1] = cost
                    else:
                        groups.append([nv, cost])

                for (av, mc) in groups:
                    if av == target:
                        val = mc + nums[i]
                        if i not in curr or curr[i] > val:
                            curr[i] = val
                        break
                    elif av < target:
                        break

            prev = curr

        return prev.get(n - 1, -1)

