    m = int(data[idx]); idx += 1
    pattern = []
    for i in range(m):
        pattern.append(int(data[idx])); idx += 1
    sol = Solution()
    print(sol.countMatchingSubarrays(nums, pattern))

if __name__ == "__main__":
