def solve():
    N = int(input())
    grid = [[0]*N for _ in range(N)]
    cx = cy = N//2

    path = []

    def spiral(r1, c1, r2, c2):
        if r1 > r2 or c1 > c2:
            return
        if r1 == r2 and c1 == c2:
            if not (r1 == cx and c1 == cy):
                path.append((r1, c1))
            return
        # top row left to right
        for c in range(c1, c2+1):
            path.append((r1, c))
        # right col top+1 to bottom
        for r in range(r1+1, r2+1):
            path.append((r, c2))
        # bottom row right-1 to left
        for c in range(c2-1, c1-1, -1):
            path.append((r2, c))
        # left col bottom-1 to top+1
        for r in range(r2-1, r1+1, -1):
            path.append((r, c1))
        spiral(r1+1, c1+1, r2-1, c2-1)

    spiral(0, 0, N-1, N-1)
    path = [(r,c) for (r,c) in path if not (r==cx and c==cy)]

    for i, (r,c) in enumerate(path):
        grid[r][c] = i+1
    grid[cx][cy] = 'T'

    for row in grid:
        print(*row)

solve()

