from collections import Counter
from typing import List
import sys

class Solution:
    def maximumLength(self, nums: List[int]) -> int:
        count = Counter(nums)

        # Special case for 1
        if 1 in count:
            c = count[1]
            if c % 2 == 0:
                ans = c - 1
            else:
                ans = c
        else:
            ans = 1

        for x in count:
            if x == 1:
                continue
            cur = x
            length = 0
            while cur in count and count[cur] >= 2:
                length += 2
                if cur > 10**9 // cur:
                    break
                cur = cur * cur
            if cur in count and count[cur] >= 1:
                length += 1
            if length == 0:
                length = 1
            ans = max(ans, length)

        return ans

if __name__ == '__main__':
    data = sys.stdin.read().split()
    nums = list(map(int, data))
    sol = Solution()
    print(sol.maximumLength(nums))

def is_nested(string):
    open_count = 0
    flag = False
    for ch in string:
        if ch == '[':
            open_count += 1
        else:
            if open_count >= 2:
                flag = True
            open_count = max(0, open_count - 1)
            if flag and open_count >= 1:
                return True
    return False

